(() => {
  "use strict";

  const SCHEMA = {
    roots: ["/系统", "/规则", "/角色"],
    rolePages: ["衣着", "信息", "状态", "事件", "敏感", "效果", "劣迹", "改造", "物品"],
    systemFields: [
      "当前年份",
      "当前日期",
      "当前时间",
      "当前地点",
      "当前事件",
      "当前出场角色",
      "MC能量",
      "MC能量上限",
      "持有零花钱",
      "星光点",
      "催眠APP订阅等级",
      "主角可疑度",
      "_当前周几",
      "_当前日程",
      "_当前特殊日期",
      "_user身份",
      "持有物品",
      "_课程表"
    ],
    roleInfoFields: ["姓名", "性别", "_年龄", "社团或职业", "身高", "体重", "三围", "阴茎长度", "绰号", "绰号已认可"],
    roleStateFields: ["好感度", "警戒度", "服从度", "性欲", "快感值", "是否派遣中"],
    ruleFields: ["名称", "内容", "目标范围", "生效范围", "来源", "地点ID", "地点名", "地图层级", "地点路径", "持续类型"]
  };

  function expose() {
    globalThis.HypnoAppRevisedSchema = SCHEMA;
    try {
      if (typeof globalThis.Mvu?.setSchema === "function") {
        globalThis.Mvu.setSchema(SCHEMA);
      }
    } catch {
      // 没有 setSchema 时仍通过全局对象暴露给其他脚本。
    }
  }

  async function boot() {
    try {
      if (typeof globalThis.waitGlobalInitialized === "function") {
        await globalThis.waitGlobalInitialized("Mvu");
      }
    } catch {
      // 等待失败不阻断暴露。
    }
    expose();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => void boot(), { once: true });
  } else {
    void boot();
  }
})();

(() => {
  "use strict";

  const GLOBAL_KEY = "__HYPNO_APP_REVISED_VARIABLE_REPAIR_V1__";
  const state = globalThis[GLOBAL_KEY] ||= { registered: false };

  function repairMissingValue(text) {
    const source = String(text || "").trim();
    if (!source.startsWith("[") || !source.endsWith("]")) return null;
    let repaired = false;
    let output = "";
    let cursor = 0;
    const pattern = /\{\s*"op"\s*:\s*"(?:add|replace)"\s*,\s*"path"\s*:\s*"(?:\\.|[^"\\])*"\s*:\s*(?=\s*[\[{])/g;
    for (const match of source.matchAll(pattern)) {
      const start = match.index ?? -1;
      if (start < 0) continue;
      const fragment = match[0];
      const separator = fragment.lastIndexOf(":");
      if (separator < 0) continue;
      output += source.slice(cursor, start);
      output += `${fragment.slice(0, separator)},"value":${fragment.slice(separator + 1)}`;
      cursor = start + fragment.length;
      repaired = true;
    }
    if (!repaired) return null;
    return output + source.slice(cursor);
  }

  function protectRoleRoots(commands) {
    if (!Array.isArray(commands)) return commands;
    return commands.filter((command) => {
      if (!command || typeof command !== "object") return false;
      const path = String(command.path || "");
      if (!path.startsWith("/角色")) return true;
      const parts = path.split("/").filter(Boolean);
      return parts.length > 2;
    });
  }

  function handleParsed(commands) {
    const repairedText = repairMissingValue(commands);
    const protectedCommands = protectRoleRoots(commands);
    return typeof repairedText === "string" ? repairedText : protectedCommands;
  }

  function register() {
    if (state.registered) return true;
    const eventName = globalThis.Mvu?.events?.COMMAND_PARSED;
    if (!eventName || typeof globalThis.eventOn !== "function") return false;
    globalThis.eventOn(eventName, handleParsed);
    state.registered = true;
    return true;
  }

  globalThis.HypnoAppRevisedVariableRepair = {
    repairMissingValue,
    protectRoleRoots,
    handleParsed,
    register
  };

  register();
})();

(() => {
  "use strict";

  const INJECTION_ID = "hypno-app-revised-current-operation-gate";
  const STATE_KEY = "__HYPNO_APP_REVISED_CURRENT_OPERATION_GATE__";
  const PREFIX = "[本轮操作执行闸门]\n下方容器是当前最新用户消息中的本轮操作。它是本次回复唯一必须先完成的行动队列。\n\n";

  try {
    globalThis[STATE_KEY]?.dispose?.();
  } catch {}

  let disposed = false;
  let injectionHandle = null;
  const subscriptions = [];
  const boundEvents = new Set();

  function context() {
    try {
      return globalThis.SillyTavern?.getContext?.() || globalThis.getContext?.() || null;
    } catch {
      return null;
    }
  }

  function rawMessageText(message) {
    return message?.mes ?? message?.message ?? message?.content ?? message?.text ?? "";
  }

  function latestVisibleUserMessage() {
    const chat = context()?.chat || [];
    for (let index = chat.length - 1; index >= 0; index -= 1) {
      const message = chat[index];
      if (!message || message.is_system || message.isSystem || message.hidden || message.is_hidden) continue;
      if (message.is_user || message.isUser || message.from_user) return message;
    }
    return null;
  }

  function extractOperationBlock(text) {
    const match = String(text || "").match(/<本轮操作>([\s\S]*?)<\/本轮操作>/);
    return match?.[1]?.trim() || "";
  }

  function clearPrompt() {
    try {
      injectionHandle?.uninject?.();
    } catch {}
    injectionHandle = null;
    try {
      globalThis.uninjectPrompts?.([INJECTION_ID]);
    } catch {}
  }

  function apply() {
    clearPrompt();
    if (disposed) return false;
    const latest = latestVisibleUserMessage();
    const block = extractOperationBlock(rawMessageText(latest));
    if (!block) return false;
    const prompt = PREFIX + `<本轮操作>\n${block}\n</本轮操作>`;
    if (typeof globalThis.setExtensionPrompt === "function") {
      injectionHandle = globalThis.setExtensionPrompt(INJECTION_ID, prompt, 0, 0, false, 0);
    }
    return Boolean(injectionHandle);
  }

  function subscribe(name) {
    if (!name || boundEvents.has(name) || typeof globalThis.eventOn !== "function") return;
    try {
      const handler = () => apply();
      const handle = globalThis.eventOn(name, handler);
      subscriptions.push({ name, handler, handle });
      boundEvents.add(name);
    } catch {}
  }

  function boot() {
    apply();
    const events = globalThis.tavern_events || {};
    [
      events.GENERATION_STARTED,
      events.MESSAGE_SENT,
      events.MESSAGE_SWIPED,
      events.MESSAGE_UPDATED,
      events.CHAT_CHANGED,
      "generation_started",
      "message_sent",
      "message_swiped",
      "message_updated",
      "chat_changed"
    ].filter(Boolean).forEach(subscribe);
  }

  function dispose() {
    disposed = true;
    clearPrompt();
    for (const item of subscriptions.splice(0)) {
      try {
        item.handle?.stop?.() || item.handle?.unsubscribe?.() || item.handle?.off?.();
        if (typeof globalThis.eventOff === "function") globalThis.eventOff(item.name, item.handler);
      } catch {}
    }
  }

  globalThis[STATE_KEY] = { dispose };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot, { once: true });
  } else {
    boot();
  }
})();

(() => {
  "use strict";

  const INJECTION_ID = "hypno-app-revised-latest-user-guard";
  const STATE_KEY = "__HYPNO_APP_REVISED_LATEST_USER_GUARD__";
  const MAX_LENGTH = 4000;

  try {
    globalThis[STATE_KEY]?.dispose?.();
  } catch {}

  let disposed = false;
  let handle = null;
  const subscriptions = [];
  const boundEvents = new Set();

  function context() {
    try {
      return globalThis.SillyTavern?.getContext?.() || globalThis.getContext?.() || null;
    } catch {
      return null;
    }
  }

  function rawMessageText(message) {
    return message?.mes ?? message?.message ?? message?.content ?? message?.text ?? "";
  }

  function latestUserMessage() {
    const chat = context()?.chat || [];
    for (let index = chat.length - 1; index >= 0; index -= 1) {
      const message = chat[index];
      if (!message || message.is_system || message.isSystem || message.hidden || message.is_hidden) continue;
      if (message.is_user || message.isUser || message.from_user) return message;
    }
    return null;
  }

  function clear() {
    try {
      handle?.uninject?.();
    } catch {}
    handle = null;
    try {
      globalThis.uninjectPrompts?.([INJECTION_ID]);
    } catch {}
  }

  function apply() {
    clear();
    if (disposed) return false;
    const message = latestUserMessage();
    const text = rawMessageText(message);
    if (!text || text.length > MAX_LENGTH || text.includes("<本轮操作>")) return false;
    const prompt = `[最新用户消息完整性守卫]\n当前最新用户消息已保留，正文模型必须优先响应该消息。\n`;
    if (typeof globalThis.setExtensionPrompt === "function") {
      handle = globalThis.setExtensionPrompt(INJECTION_ID, prompt, 0, 0, false, 0);
    }
    return Boolean(handle);
  }

  function boot() {
    apply();
    const events = globalThis.tavern_events || {};
    [
      events.GENERATION_STARTED,
      events.MESSAGE_SENT,
      events.MESSAGE_SWIPED,
      events.MESSAGE_UPDATED,
      events.CHAT_CHANGED,
      "generation_started",
      "message_sent",
      "message_swiped",
      "message_updated",
      "chat_changed"
    ].filter(Boolean).forEach((name) => {
      if (!name || boundEvents.has(name) || typeof globalThis.eventOn !== "function") return;
      try {
        const handler = () => apply();
        const registration = globalThis.eventOn(name, handler);
        subscriptions.push({ name, handler, handle: registration });
        boundEvents.add(name);
      } catch {}
    });
  }

  function dispose() {
    disposed = true;
    clear();
    for (const item of subscriptions.splice(0)) {
      try {
        item.handle?.stop?.() || item.handle?.unsubscribe?.() || item.handle?.off?.();
        if (typeof globalThis.eventOff === "function") globalThis.eventOff(item.name, item.handler);
      } catch {}
    }
  }

  globalThis[STATE_KEY] = { dispose };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot, { once: true });
  } else {
    boot();
  }
})();

(() => {
  "use strict";

  const NAMESPACE = "hypno-app-revised";
  const SETTINGS_KEY = "hypno-app-revised:settings:v1";
  const STATE_KEY = "hypno-app-revised:state:v1";
  const handlers = new Map();

  const defaultState = () => ({
    roles: [],
    locations: [],
    rules: [],
    plot: "",
    icon: "pulse",
    crack: { mc: false, money: false, vip: false }
  });

  const defaultSettings = () => ({
    mode: "custom",
    endpoint: "",
    apiKey: "",
    model: "",
    maxTokens: 1024,
    temperature: 0.7,
    preset: ""
  });

  function clone(value) {
    return JSON.parse(JSON.stringify(value));
  }

  function loadJson(key, fallback) {
    try {
      const value = JSON.parse(localStorage.getItem(key) || "null");
      return value && typeof value === "object" ? value : fallback;
    } catch {
      return fallback;
    }
  }

  function saveJson(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      // 私密或存储不可用时仍保持内存状态。
    }
  }

  let state = {
    ...defaultState(),
    ...loadJson(STATE_KEY, defaultState())
  };
  let settings = {
    ...defaultSettings(),
    ...loadJson(SETTINGS_KEY, defaultSettings())
  };

  function normalizeState(value) {
    const next = {
      ...defaultState(),
      ...(value || {})
    };
    next.roles = Array.isArray(next.roles) ? next.roles : [];
    next.locations = Array.isArray(next.locations) ? next.locations : [];
    next.rules = Array.isArray(next.rules) ? next.rules : [];
    next.crack = { mc: false, money: false, vip: false, ...(next.crack || {}) };
    return next;
  }

  function normalizeSettings(value) {
    return {
      ...defaultSettings(),
      ...(value || {})
    };
  }

  state = normalizeState(state);
  settings = normalizeSettings(settings);

  async function getWorldInfo() {
    const st = globalThis.SillyTavern || {};
    if (typeof st.loadWorldInfo === "function") {
      try {
        const world = await st.loadWorldInfo();
        if (world && Array.isArray(world.entries)) return world;
      } catch {
        // 回退到角色卡字段。
      }
    }
    if (typeof st.getCharacterCardFields === "function") {
      const fields = st.getCharacterCardFields();
      const world = fields && fields.character_book;
      if (world && Array.isArray(world.entries)) return world;
    }
    return { name: "催眠APP（改）", entries: [] };
  }

  async function saveWorldInfo(world) {
    const st = globalThis.SillyTavern || {};
    if (typeof st.saveWorldInfo === "function") {
      await st.saveWorldInfo(world);
    } else if (typeof st.getCharacterCardFields === "function") {
      const fields = st.getCharacterCardFields();
      if (fields) fields.character_book = world;
    }
    if (typeof st.reloadWorldInfoEditor === "function") st.reloadWorldInfoEditor();
    if (typeof st.updateWorldInfoList === "function") st.updateWorldInfoList();
  }

  function makeEntry(comment, content, keys = [], insertionOrder = 100, constant = false) {
    return {
      id: Date.now() + Math.floor(Math.random() * 100000),
      keys,
      secondary_keys: [],
      comment,
      content,
      constant,
      selective: false,
      insertion_order: insertionOrder,
      enabled: true,
      position: "before_char",
      use_regex: true,
      extensions: {
        position: 0,
        exclude_recursion: false,
        display_index: 0,
        probability: 100,
        useProbability: true,
        depth: 4,
        selectiveLogic: 0,
        outlet_name: "",
        group: "",
        group_override: false,
        group_weight: 100,
        prevent_recursion: false,
        delay_until_recursion: false,
        scan_depth: null,
        match_whole_words: null,
        use_group_scoring: false,
        case_sensitive: null,
        automation_id: "",
        role: 0,
        vectorized: false,
        sticky: 0,
        cooldown: 0,
        delay: 0,
        match_persona_description: false,
        match_character_description: false,
        match_character_personality: false,
        match_character_depth_prompt: false,
        match_scenario: false,
        match_creator_notes: false,
        triggers: [],
        ignore_budget: false
      }
    };
  }

  function personaText(role) {
    const persona = role?.draft?.persona || {};
    return Object.entries(persona)
      .filter(([, value]) => value !== undefined && value !== null && value !== "")
      .map(([key, value]) => `${key}: ${Array.isArray(value) ? value.join("、") : value}`)
      .join("\n");
  }

  function variablesText(role) {
    return JSON.stringify(role?.draft?.variables || {}, null, 2);
  }

  function syncWorldEntries(world) {
    const entries = Array.isArray(world.entries) ? world.entries : [];
    let order = 100;

    for (let index = entries.length - 1; index >= 0; index -= 1) {
      const comment = entries[index].comment || "";
      if (
        comment.startsWith("[角色-人设]") ||
        comment.startsWith("[角色-变量]") ||
        comment.startsWith("[档案]") ||
        comment.startsWith("[地点]") ||
        comment.startsWith("[规则]") ||
        comment === "剧情大纲"
      ) {
        entries.splice(index, 1);
      }
    }

    for (const role of state.roles) {
      const name = String(role.name || role.draft?.persona?.姓名 || "未命名角色");
      const aliases = Array.isArray(role.draft?.persona?.别名) ? role.draft.persona.别名 : [];
      entries.push(makeEntry(`[角色-人设]${name}`, personaText(role), [name, ...aliases], (order += 1)));
      entries.push(makeEntry(`[角色-变量]${name}`, variablesText(role), [name, `${name}变量`], (order += 1)));
      entries.push(makeEntry(`[档案]${name}`, `<角色档案>\n${personaText(role)}\n\n变量:\n${variablesText(role)}\n</角色档案>`, [name], (order += 1)));
    }

    for (const location of state.locations) {
      const name = String(location.name || "未命名地点");
      entries.push(makeEntry(`[地点]${name}`, `<地点>\n名称: ${name}\n描述: ${location.description || ""}\n</地点>`, [name], (order += 1)));
    }

    for (const rule of state.rules) {
      entries.push(makeEntry(`[规则]${rule.id}`, `<规则>\n类型: ${rule.type || "永久"}\n范围: ${rule.scope || "整个故事"}\n时间: ${rule.time || "永久"}\n内容: ${rule.text || ""}\n</规则>`, [], (order += 1)));
    }

    if (state.plot) {
      entries.push(makeEntry("剧情大纲", `<剧情大纲>\n${state.plot}\n</剧情大纲>`, [], (order += 1), true));
    }

    const names = state.roles.map((role) => String(role.name || role.draft?.persona?.姓名 || "未命名角色"));
    const listIndex = entries.findIndex((entry) => entry.comment === "人物列表");
    const listContent = `人物列表:\n${names.length ? names.map((name) => `- ${name}`).join("\n") : "- 暂无角色"}`;
    if (listIndex >= 0) entries[listIndex].content = listContent;
    else entries.push(makeEntry("人物列表", listContent, [], (order += 1), true));

    const archiveIndex = entries.findIndex((entry) => entry.comment === "APP档案");
    const archiveContent = `APP档案:\n${names.length ? names.map((name) => `- ${name}`).join("\n") : "- 暂无角色"}`;
    if (archiveIndex >= 0) entries[archiveIndex].content = archiveContent;
    else entries.push(makeEntry("APP档案", archiveContent, [], (order += 1), true));

    world.entries = entries;
    world.name = "催眠APP（改）";
    return world;
  }

  async function syncWorldbook() {
    const world = await getWorldInfo();
    syncWorldEntries(world);
    await saveWorldInfo(world);
  }

  async function syncMvu() {
    const mvu = globalThis.Mvu;
    if (!mvu) return;
    let data = typeof mvu.getMvuData === "function" ? mvu.getMvuData() : null;
    if (!data || typeof data !== "object") data = {};
    if (!data.stat_data || typeof data.stat_data !== "object") data.stat_data = {};
    const roleData = {};
    for (const role of state.roles) {
      const name = String(role.name || role.draft?.persona?.姓名 || "未命名角色");
      roleData[name] = role.draft?.variables || {};
    }
    data.stat_data.角色 = roleData;
    const currentCharacters = Array.isArray(data.stat_data.系统?.当前出场角色)
      ? data.stat_data.系统.当前出场角色.filter((name) => roleData[name])
      : [];
    data.stat_data.系统 = {
      ...(data.stat_data.系统 || {}),
      当前出场角色: currentCharacters
    };
    if (typeof mvu.replaceMvuData === "function") await mvu.replaceMvuData(data);
  }

  function register(action, handler) {
    handlers.set(action, handler);
  }

  async function handle(action, payload = {}) {
    const handler = handlers.get(action);
    if (!handler) throw new Error(`未知操作：${action}`);
    return handler(payload);
  }

  globalThis.addEventListener("message", async (event) => {
    const data = event.data;
    if (!data || data.namespace !== NAMESPACE || data.type !== "request" || !data.id) return;
    try {
      const result = await handle(data.action, data.payload || {});
      event.source?.postMessage?.({ namespace: NAMESPACE, type: "response", id: data.id, ok: true, result }, "*");
    } catch (error) {
      event.source?.postMessage?.({ namespace: NAMESPACE, type: "response", id: data.id, ok: false, error: error.message || "操作失败" }, "*");
    }
  });

  globalThis.HypnoAppRevisedCore = {
    namespace: NAMESPACE,
    register,
    handle,
    clone,
    getState: () => clone(normalizeState(state)),
    setState(next) {
      state = normalizeState(next);
      saveJson(STATE_KEY, state);
      return clone(state);
    },
    getSettings: () => clone(normalizeSettings(settings)),
    setSettings(next) {
      settings = normalizeSettings(next);
      saveJson(SETTINGS_KEY, settings);
      return clone(settings);
    },
    getWorldInfo,
    saveWorldInfo,
    syncWorldbook,
    syncMvu,
    makeEntry,
    personaText,
    variablesText,
    normalizeState,
    normalizeSettings
  };
})();

(() => {
  "use strict";

  const core = globalThis.HypnoAppRevisedCore;
  if (!core) return;

  function parseJsonText(text) {
    if (!text) return null;
    const trimmed = String(text).trim();
    try {
      return JSON.parse(trimmed);
    } catch {
      const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/i);
      if (fenced) {
        try {
          return JSON.parse(fenced[1].trim());
        } catch {
          return null;
        }
      }
      return null;
    }
  }

  async function callCustomChat(messages, jsonMode = false) {
    const settings = core.getSettings();
    const endpoint = String(settings.endpoint || "").trim();
    if (!endpoint) throw new Error("请先填写 API 端点");
    const chatUrl = endpoint.includes("/chat/completions")
      ? endpoint
      : `${endpoint.replace(/\/+$/, "")}/chat/completions`;
    const body = {
      model: settings.model || "gpt-4o-mini",
      messages,
      temperature: Number(settings.temperature ?? 0.7),
      max_tokens: Number(settings.maxTokens ?? 1024)
    };
    if (jsonMode) body.response_format = { type: "json_object" };
    const response = await fetch(chatUrl, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${settings.apiKey || ""}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(body)
    });
    if (!response.ok) throw new Error(`API 请求失败：${response.status}`);
    const data = await response.json();
    const text = data?.choices?.[0]?.message?.content || "";
    return parseJsonText(text) || { content: text };
  }

  async function callCustomModels(endpoint, apiKey) {
    const base = String(endpoint || "").trim();
    if (!base) throw new Error("请先填写 API 端点");
    const modelsUrl = base.includes("/chat/completions")
      ? base.replace(/\/chat\/completions$/, "/models")
      : `${base.replace(/\/+$/, "")}/models`;
    const response = await fetch(modelsUrl, {
      headers: {
        Authorization: `Bearer ${apiKey || ""}`,
        "Content-Type": "application/json"
      }
    });
    if (!response.ok) throw new Error(`获取模型失败：${response.status}`);
    const data = await response.json();
    if (Array.isArray(data.data)) return data.data.map((item) => item.id).filter(Boolean);
    if (Array.isArray(data)) return data.map((item) => (typeof item === "string" ? item : item.id)).filter(Boolean);
    return [];
  }

  core.register("api:get", () => core.getSettings());
  core.register("api:set", (payload) => core.setSettings(payload));
  core.register("api:presets", async () => {
    try {
      const presets = await globalThis.SillyTavern?.getPresetManager?.()?.getPresets?.();
      if (Array.isArray(presets)) return presets.map((item) => item.name || item).filter(Boolean);
    } catch {
      // 无可用预设时返回空数组。
    }
    return [];
  });
